cat > /tmp/batch.mjs <<'EOF'
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test11_executable';
function run(args){ try { return {out: execFileSync(EXE,args,{encoding:'utf8',maxBuffer:1<<28}), rc:0}; } catch(e){ return {out:(e.stdout||'')+(e.stderr||''), rc:e.status, err:true}; } }
function mode(text,which){
  const args = which==='a'?['--a',text,'--b','','--c','']:which==='b'?['--a','','--b',text,'--c','']:['--a','','--b','','--c',text];
  const r=run(args);
  if(r.err) return '!!ERR rc='+r.rc+' '+r.out;
  const lead = which==='a'?0:which==='b'?1:2;
  const trail= which==='a'?3:which==='b'?2:1;
  return r.out.slice(lead, r.out.length-trail);
}
// input: JSON array of strings, one per line? No: file contains JSON array.
const inputs = JSON.parse(readFileSync(process.argv[2],'utf8'));
for(const md of inputs){
  const core=mode(md,'a'), tables=mode(md,'b'), extra=mode(md,'c');
  console.log(JSON.stringify({md,core,tables,extra}));
}
EOF
echo ok

